"""tool.py - Production duplicate transaction auditor for business records."""

import argparse
import logging
from pathlib import Path
import sys
import pandas as pd

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)],
)


def parse_args():
    parser = argparse.ArgumentParser(
        description="Detect duplicate records and export side-by-side audit files."
    )
    parser.add_argument(
        "--input", "-i", required=True, help="Path to source CSV or Excel file."
    )
    parser.add_argument(
        "--output", "-o", default="duplicates_flagged.csv", help="Output CSV path."
    )
    parser.add_argument(
        "--subset",
        "-s",
        nargs="+",
        default=["client", "amount"],
        help="Column names to consider for duplication.",
    )
    parser.add_argument(
        "--case-insensitive",
        action="store_true",
        help="Normalize string columns to lowercase before checking.",
    )
    return parser.parse_args()


def load_data(filepath: Path) -> pd.DataFrame:
    if not filepath.exists():
        raise FileNotFoundError(f"Input file does not exist: {filepath}")
    if filepath.suffix.lower() in [".xlsx", ".xls"]:
        return pd.read_excel(filepath)
    return pd.read_csv(filepath)


def find_duplicates(
    df: pd.DataFrame, subset: list, case_insensitive: bool
) -> pd.DataFrame:
    for col in subset:
        if col not in df.columns:
            raise KeyError(f"Column '{col}' was not found in data: {list(df.columns)}")

    eval_df = df.copy()
    if case_insensitive:
        for col in subset:
            if eval_df[col].dtype == object:
                eval_df[col] = eval_df[col].astype(str).str.strip().str.lower()

    mask = eval_df.duplicated(subset=subset, keep=False)
    flagged = df[mask].sort_values(by=subset)
    return flagged


def main():
    args = parse_args()
    src_path = Path(args.input)
    out_path = Path(args.output)

    try:
        logging.info("Reading records from %s", src_path)
        df = load_data(src_path)
        logging.info("Loaded %d total records. Scanning columns: %s", len(df), args.subset)

        dupes = find_duplicates(df, args.subset, args.case_insensitive)
        count = len(dupes)

        if count == 0:
            logging.info("No duplicate rows identified.")
            return

        out_path.parent.mkdir(parents=True, exist_ok=True)
        dupes.to_csv(out_path, index=False)
        logging.info("Wrote %d duplicate records to %s", count, out_path)

    except Exception as err:
        logging.error("Audit failed: %s", err)
        sys.exit(1)


if __name__ == "__main__":
    main()
